-- Migration: sign-in with WorkEasy360 Accounts (docs/workeasy360-sso.md).
-- Part A is generated by 'prisma migrate diff' (only this change's statements: the diff against the database also lists
-- tables that later phases created without Prisma models, which this migration leaves alone). Part B is hand-written
-- security (constraints, RLS, grants, SECURITY DEFINER functions). Additive: no existing column, grant or policy is
-- removed; app.resolve_session is recreated with five more output columns.

-- ═══ Part A: generated DDL ═══
-- AlterTable
ALTER TABLE "organizations" ADD COLUMN     "workeasy360_organization_id" UUID;

-- AlterTable
ALTER TABLE "sessions" ADD COLUMN     "bound_org_id" UUID,
ADD COLUMN     "workeasy360_id_token" TEXT,
ADD COLUMN     "workeasy360_issuer" TEXT,
ADD COLUMN     "workeasy360_organization_id" UUID,
ADD COLUMN     "workeasy360_sid" TEXT,
ADD COLUMN     "workeasy360_subject" TEXT;

-- AlterTable
ALTER TABLE "user_identities" ADD COLUMN     "issuer" TEXT;

-- CreateTable
CREATE TABLE "workeasy360_login_flows" (
    "id_hash" TEXT NOT NULL,
    "state" TEXT NOT NULL,
    "nonce" TEXT NOT NULL,
    "code_verifier" TEXT NOT NULL,
    "organization_hint" UUID,
    "return_to" TEXT,
    "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "expires_at" TIMESTAMPTZ(3) NOT NULL,

    CONSTRAINT "workeasy360_login_flows_pkey" PRIMARY KEY ("id_hash")
);

-- CreateTable
CREATE TABLE "workeasy360_entitlement_answers" (
    "key" TEXT NOT NULL,
    "value" TEXT NOT NULL,
    "updated_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "expires_at" TIMESTAMPTZ(3),

    CONSTRAINT "workeasy360_entitlement_answers_pkey" PRIMARY KEY ("key")
);

-- CreateTable
CREATE TABLE "workeasy360_logout_tokens" (
    "issuer" TEXT NOT NULL,
    "jti" TEXT NOT NULL,
    "received_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "expires_at" TIMESTAMPTZ(3) NOT NULL,

    CONSTRAINT "workeasy360_logout_tokens_pkey" PRIMARY KEY ("issuer","jti")
);

-- CreateIndex
CREATE INDEX "workeasy360_login_flows_expires_at_idx" ON "workeasy360_login_flows"("expires_at");

-- CreateIndex
CREATE INDEX "workeasy360_logout_tokens_expires_at_idx" ON "workeasy360_logout_tokens"("expires_at");

-- CreateIndex
CREATE UNIQUE INDEX "organizations_workeasy360_organization_id_key" ON "organizations"("workeasy360_organization_id");

-- CreateIndex
CREATE INDEX "sessions_workeasy360_issuer_workeasy360_subject_idx" ON "sessions"("workeasy360_issuer", "workeasy360_subject");

-- CreateIndex
CREATE INDEX "sessions_workeasy360_issuer_workeasy360_sid_idx" ON "sessions"("workeasy360_issuer", "workeasy360_sid");

-- ═══ Part B: security ═══

-- ─── 1. Domain integrity ─────────────────────────────────────────────────────────────────────────────────────────
-- A WorkEasy360 identity always names its issuer, and only WorkEasy360 identities do.
ALTER TABLE "user_identities" ADD CONSTRAINT user_identities_issuer_chk
  CHECK ((provider = 'workeasy360') = (issuer IS NOT NULL) AND (issuer IS NULL OR length(issuer) BETWEEN 1 AND 255));
-- A WorkEasy360 session is always bound to one issuer, one person, one WorkEasy360 organization and one organization here.
ALTER TABLE "sessions" ADD CONSTRAINT sessions_workeasy360_binding_chk CHECK (
  provider <> 'workeasy360'
  OR (workeasy360_issuer IS NOT NULL AND workeasy360_subject IS NOT NULL AND workeasy360_organization_id IS NOT NULL
      AND bound_org_id IS NOT NULL));
ALTER TABLE "sessions" ADD CONSTRAINT sessions_workeasy360_lengths_chk CHECK (
  coalesce(length(workeasy360_issuer), 0) <= 255 AND coalesce(length(workeasy360_subject), 0) <= 255
  AND coalesce(length(workeasy360_sid), 0) <= 255 AND coalesce(length(workeasy360_id_token), 0) <= 16384);
ALTER TABLE "workeasy360_logout_tokens" ADD CONSTRAINT workeasy360_logout_tokens_lengths_chk
  CHECK (length(issuer) BETWEEN 1 AND 255 AND length(jti) BETWEEN 1 AND 255);
ALTER TABLE "workeasy360_login_flows" ADD CONSTRAINT workeasy360_login_flows_lengths_chk
  CHECK (length(id_hash) = 64 AND length(state) <= 128 AND length(nonce) <= 128 AND length(code_verifier) BETWEEN 43 AND 128
         AND coalesce(length(return_to), 0) <= 512);

-- ─── 2. Privileges ───────────────────────────────────────────────────────────────────────────────────────────────
-- The runtime role reads organizations.workeasy360_organization_id and the new session columns through its existing
-- table-level SELECT/INSERT grants. It gets no UPDATE on any of them (the column-level UPDATE grants of
-- 20261002000000 are unchanged): a session's binding and an organization's link are fixed once written; only an
-- operator (schema owner) changes a link. The three new tables get no grants at all: only the functions below reach them.

-- ─── 3. Row-level security on the new tables (no policies: nothing but the definer functions may read them) ───────
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['workeasy360_login_flows', 'workeasy360_entitlement_answers', 'workeasy360_logout_tokens']
  LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY', t);
  END LOOP;
END $$;

-- ─── 4. Session lookup, now with the WorkEasy360 binding (return type changes: drop and recreate) ────────────────
DROP FUNCTION app.resolve_session(text);
CREATE FUNCTION app.resolve_session(p_token_hash text)
RETURNS TABLE (session_id uuid, user_id uuid, user_status text, user_email text, user_display_name text,
               user_email_verified boolean, provider text, auth_methods text[],
               created_at timestamptz, rotated_at timestamptz, idle_expires_at timestamptz,
               absolute_expires_at timestamptz, revoked_at timestamptz, is_previous_token boolean,
               workeasy360_issuer text, workeasy360_subject text, workeasy360_sid text,
               workeasy360_organization_id uuid, bound_org_id uuid)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
  SELECT s.id, s.user_id, u.status, u.email, u.display_name, u.email_verified_at IS NOT NULL, s.provider, s.auth_methods, s.created_at, s.rotated_at, s.idle_expires_at,
         s.absolute_expires_at, s.revoked_at, (s.token_hash <> p_token_hash),
         s.workeasy360_issuer, s.workeasy360_subject, s.workeasy360_sid, s.workeasy360_organization_id, s.bound_org_id
  FROM sessions s JOIN users u ON u.id = s.user_id
  WHERE s.token_hash = p_token_hash
     OR (s.previous_token_hash = p_token_hash AND s.previous_token_valid_until > now())
$$;

-- ─── 5. Linking a WorkEasy360 person: on (issuer, subject), never on email ───────────────────────────────────────
-- Outcomes:
--   linked          the identity is known under this issuer: its user
--   created         first sign-in: a new user and identity (the email is the provider's verified address)
--   email_taken     no identity yet, and the email already belongs to another user (a password account): refused,
--                   an operator links the two explicitly (docs/workeasy360-sso.md), never this function
--   issuer_conflict the subject is known under ANOTHER issuer: refused until the operator's issuer move runs
CREATE FUNCTION app.workeasy360_link_identity(p_issuer text, p_subject text, p_email text, p_display_name text)
RETURNS TABLE (user_id uuid, outcome text)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
#variable_conflict use_column
DECLARE
  v_user uuid;
  v_issuer text;
BEGIN
  IF p_issuer IS NULL OR p_subject IS NULL OR p_email IS NULL OR length(p_subject) NOT BETWEEN 1 AND 255 THEN
    RAISE EXCEPTION 'issuer, subject and email are required' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  FOR attempt IN 1..2 LOOP
    SELECT i.user_id, i.issuer INTO v_user, v_issuer FROM user_identities i
     WHERE i.provider = 'workeasy360' AND i.subject = p_subject;
    IF v_user IS NOT NULL THEN
      IF v_issuer <> p_issuer THEN
        RETURN QUERY SELECT NULL::uuid, 'issuer_conflict'::text;
        RETURN;
      END IF;
      UPDATE user_identities SET last_used_at = now() WHERE provider = 'workeasy360' AND subject = p_subject;
      UPDATE users SET email_verified_at = coalesce(email_verified_at, now()) WHERE id = v_user;
      RETURN QUERY SELECT v_user, 'linked'::text;
      RETURN;
    END IF;
    IF EXISTS (SELECT 1 FROM users u WHERE u.email_normalized = lower(p_email)) THEN
      RETURN QUERY SELECT NULL::uuid, 'email_taken'::text;
      RETURN;
    END IF;
    BEGIN
      v_user := gen_random_uuid();
      INSERT INTO users (id, email, email_normalized, display_name, email_verified_at)
        VALUES (v_user, p_email, lower(p_email), p_display_name, now());
      INSERT INTO user_identities (id, user_id, provider, subject, issuer, last_used_at)
        VALUES (gen_random_uuid(), v_user, 'workeasy360', p_subject, p_issuer, now());
      RETURN QUERY SELECT v_user, 'created'::text;
      RETURN;
    EXCEPTION WHEN unique_violation THEN
      -- A concurrent first sign-in of the same person (or the same email) won the race: look again.
      v_user := NULL;
    END;
  END LOOP;
  RETURN QUERY SELECT NULL::uuid, 'email_taken'::text;
END $$;

-- ─── 6. The organization a WorkEasy360 organization maps to (RLS hides organizations the caller is not in yet) ───
CREATE FUNCTION app.workeasy360_tenant(p_organization_id uuid)
RETURNS TABLE (org_id uuid, status text)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
  SELECT o.id, o.status FROM organizations o WHERE o.workeasy360_organization_id = p_organization_id
$$;

-- ─── 7. Pending sign-ins: saved by the start, taken (deleted) once by the callback ─────────────────────────────
CREATE FUNCTION app.workeasy360_save_flow(p_id_hash text, p_state text, p_nonce text, p_code_verifier text,
                                          p_organization_hint uuid, p_return_to text, p_ttl_seconds int)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
BEGIN
  IF p_ttl_seconds NOT BETWEEN 30 AND 3600 THEN
    RAISE EXCEPTION 'ttl out of range' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  DELETE FROM workeasy360_login_flows WHERE expires_at < now();
  INSERT INTO workeasy360_login_flows (id_hash, state, nonce, code_verifier, organization_hint, return_to, expires_at)
  VALUES (p_id_hash, p_state, p_nonce, p_code_verifier, p_organization_hint, p_return_to,
          now() + make_interval(secs => p_ttl_seconds));
END $$;

CREATE FUNCTION app.workeasy360_take_flow(p_id_hash text)
RETURNS TABLE (state text, nonce text, code_verifier text, organization_hint uuid, return_to text)
LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
  DELETE FROM workeasy360_login_flows f WHERE f.id_hash = p_id_hash AND f.expires_at > now()
  RETURNING f.state, f.nonce, f.code_verifier, f.organization_hint, f.return_to
$$;

-- ─── 8. Shared entitlement answers ─────────────────────────────────────────────────────────────────────────────
CREATE FUNCTION app.workeasy360_answer_get(p_key text)
RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
  SELECT a.value FROM workeasy360_entitlement_answers a
   WHERE a.key = p_key AND (a.expires_at IS NULL OR a.expires_at > now())
$$;

-- p_ttl_seconds NULL: kept without expiry (a denial).
CREATE FUNCTION app.workeasy360_answer_put(p_key text, p_value text, p_ttl_seconds int)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
BEGIN
  IF length(p_key) > 200 OR length(p_value) > 2000 THEN
    RAISE EXCEPTION 'answer too large' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  INSERT INTO workeasy360_entitlement_answers (key, value, updated_at, expires_at)
  VALUES (p_key, p_value, now(), CASE WHEN p_ttl_seconds IS NULL THEN NULL ELSE now() + make_interval(secs => p_ttl_seconds) END)
  ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = EXCLUDED.updated_at, expires_at = EXCLUDED.expires_at;
END $$;

-- ─── 9. Back-channel logout: record the jti once, end the sessions the token names, in one transaction ──────────
-- With sid: the sessions that WorkEasy360 sign-in opened (narrowed to the subject when the token names one).
-- With the subject alone: every live session of the person linked to (issuer, subject), however it was opened.
-- A replayed jti changes nothing (replayed = true). Ending an already ended session is not an error.
CREATE FUNCTION app.workeasy360_end_sessions(p_issuer text, p_jti text, p_subject text, p_sid text,
                                             p_acceptable_until timestamptz)
RETURNS TABLE (replayed boolean, sessions_ended int)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
  v_count int;
BEGIN
  IF p_issuer IS NULL OR p_jti IS NULL OR (p_subject IS NULL AND p_sid IS NULL) THEN
    RAISE EXCEPTION 'issuer, jti and a subject or sid are required' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  DELETE FROM workeasy360_logout_tokens WHERE expires_at < now();
  INSERT INTO workeasy360_logout_tokens (issuer, jti, expires_at)
  VALUES (p_issuer, p_jti, greatest(p_acceptable_until, now() + interval '1 minute'))
  ON CONFLICT DO NOTHING;
  IF NOT FOUND THEN
    RETURN QUERY SELECT true, 0;
    RETURN;
  END IF;
  IF p_sid IS NOT NULL THEN
    UPDATE sessions s SET revoked_at = now(), revoked_reason = 'workeasy360_logout'
     WHERE s.provider = 'workeasy360' AND s.workeasy360_issuer = p_issuer AND s.workeasy360_sid = p_sid
       AND (p_subject IS NULL OR s.workeasy360_subject = p_subject) AND s.revoked_at IS NULL;
  ELSE
    UPDATE sessions s SET revoked_at = now(), revoked_reason = 'workeasy360_logout'
     WHERE s.revoked_at IS NULL
       AND ((s.provider = 'workeasy360' AND s.workeasy360_issuer = p_issuer AND s.workeasy360_subject = p_subject)
            OR s.user_id IN (SELECT i.user_id FROM user_identities i
                              WHERE i.provider = 'workeasy360' AND i.issuer = p_issuer AND i.subject = p_subject));
  END IF;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN QUERY SELECT false, v_count;
END $$;

REVOKE ALL ON FUNCTION app.resolve_session(text), app.workeasy360_link_identity(text, text, text, text),
  app.workeasy360_tenant(uuid), app.workeasy360_save_flow(text, text, text, text, uuid, text, int),
  app.workeasy360_take_flow(text), app.workeasy360_answer_get(text), app.workeasy360_answer_put(text, text, int),
  app.workeasy360_end_sessions(text, text, text, text, timestamptz) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app.resolve_session(text), app.workeasy360_link_identity(text, text, text, text),
  app.workeasy360_tenant(uuid), app.workeasy360_save_flow(text, text, text, text, uuid, text, int),
  app.workeasy360_take_flow(text), app.workeasy360_answer_get(text), app.workeasy360_answer_put(text, text, int),
  app.workeasy360_end_sessions(text, text, text, text, timestamptz) TO workeasy_app;
